-- Maximum Subarray Sum (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$maximum-subarray-sum$q$, $q$Maximum Subarray Sum$q$, $q$Find the largest possible sum of a contiguous, non-empty part of the array.

The array can contain negative numbers. If every number is negative, the answer is the largest (least negative) single element.$q$, $q$Medium$q$, $q$Dynamic Programming$q$, 'code', ARRAY[$q$array$q$, $q$dynamic-programming$q$, $q$kadane$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n.\n    # Line 2: n integers.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n.\n// Line 2: n integers.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n.\n        // Line 2: n integers.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n.\n    // Line 2: n integers.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n.\n    // Line 2: n integers.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "8\n-2 1 -3 4 -1 2 1 -5", "output": "6", "explanation": "The subarray 4, -1, 2, 1 sums to 6."}, {"input": "3\n-4 -2 -9", "output": "-2", "explanation": "All values are negative, so take the single best element."}]$q$::jsonb, ARRAY[$q$1 ≤ n ≤ 10 000$q$, $q$-10^4 ≤ a[i] ≤ 10^4$q$]::text[], 25, 1008, 2000, 262144, $q$Line 1: n.
Line 2: n integers.$q$, $q$One integer, the maximum sum.$q$, $q$Let best_here be the best sum of a subarray ending at the current position. It is either the current element alone or the current element added to the previous best_here: best_here = max(a[i], best_here + a[i]). The answer is the maximum over all positions. Start best with the first element, not 0, so that all-negative arrays are handled. O(n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

